ne_r1,r.claude_r2,r.engine_r2,r.engine_r3,r.challenger_r3,r.defender_r4,r.challenger_r4), '(\m[1-3]? ?[A-Z][a-z]+) ([0-9]+):[0-9]+(?:[-–][0-9]+)?, ([0-9]+) [A-Z][a-z]+', 'g') m where r.citation_check::text like '%"ref": "'||m[1]||' '||m[2]||':'||m[3]||'"%'))::bigint fired union all select '436' ask, (exists(select 1 from r where r.review_notes ~ 'KJV renders: ([^,)]+, ){24}' or r.review_notes ~ 'KJV renders: [^)]* and [0-9]+ more\)')) cse, ((select case when r.review_notes ~ 'KJV renders: ([^,)]+, ){24}' then 0 else (select count(*) from regexp_matches(r.review_notes, 'KJV renders: [^)]* and [0-9]+ more\)', 'g')) end from r))::bigint fired union all select '437' ask, (exists(select 1 from r)) cse, ((select case when exists(select 1 from j where j.judge_seat in ('ember','glm_legal','qwen','alt_minimax31') or j.judge_api_model ~* '(minimax|hunyuan|hy4|muse-ember|glm-5\.3-flashx-legal|qwen3\.8)') or exists(select 1 from r where concat_ws(' ',r.defender_model,r.challenger_model) ~* '(minimax|hunyuan|hy4|muse-ember|glm-5\.3-flashx-legal|qwen3\.8)') then 0 else 1 end))::bigint fired union all select '438' ask, (exists(select 1 from r where (regexp_match(r.review_notes, 'ASK 406 forms: ([0-9]+) glosses read, ([0-9]+) left out'))[1]::int + (regexp_match(r.review_notes, 'ASK 406 forms: ([0-9]+) glosses read, ([0-9]+) left out'))[2]::int > 60)) cse, ((select case when (regexp_match(r.review_notes, 'ASK 406 forms: ([0-9]+) glosses read, ([0-9]+) left out'))[1]::int > 60 then 1 else 0 end from r))::bigint fired union all select '439' ask, (exists(select 1 from r where r.review_notes ~ 'ASK 406 forms: ')) cse, ((select count(*) from r where r.review_notes ~ 'ASK 406 forms: [0-9]+ glosses read, [0-9]+ left out by the 250-gloss and 100-number caps\)'))::bigint fired) ev) res from (values ('ODV1-39266-7g9lzgbr'),('ODV1-26163-yhz15fmm'),('ODV1-38593-vh0jqefy'),('ODV1-24355-x4vw3cmx'),('ODV1-32157-13dt08rh'),('ODV1-39015-pnpoj45j')) t(tok)